343| \section{练习}
344| 
345| \begin{exercise}[$\star$]\label{exo:g10:concentration-and-dilution:1}
346| 将\qty{5.0}{g}糖溶解，配成\qty{250}{mL}溶液。
347| 计算该糖溶液的质量浓度，单位为克每升。
348| \end{exercise}
349| 
350| \begin{exercise}[$\star$]\label{exo:g10:concentration-and-dilution:2}
351| 某\qty{200}{mL}溶液中含有\qty{0.050}{mol}葡萄糖。
352| 计算其物质的量浓度。
353| \end{exercise}
354| 
355| \begin{exercise}[$\star$]\label{exo:g10:concentration-and-dilution:3}
356| 配制\qty{100.0}{mL}浓度为\qty{0.10}{mol/L}的溶液，
357| 需称取多少克无水硫酸铜\ce{CuSO4}？
358| \end{exercise}
359| 
360| \begin{exercise}[$\star$]\label{exo:g10:concentration-and-dilution:4}
361| 将\qty{1.0}{mol/L}的母液稀释至\qty{0.050}{mol/L}。
362| 求稀释倍数。配制\qty{100.0}{mL}稀释后的溶液，需要多少体积的母液？
363| \end{exercise}
364| 
365| \begin{exercise}[$\star$]\label{exo:g10:concentration-and-dilution:5}
366| 氯化钠溶液的物质的量浓度为\qty{0.10}{mol/L}。
367| 求其质量浓度。
368| \end{exercise}
369| 
370| \begin{exercise}[$\star\star$]\label{exo:g10:concentration-and-dilution:6}
371| 配制\qty{250.0}{mL}浓度为\qty{0.020}{mol/L}的溶液，
372| 需取多少体积浓度为\qty{0.50}{mol/L}的母液？
373| 指出所用的两种玻璃仪器。
374| \end{exercise}
375| 
376| \begin{exercise}[$\star\star$]\label{exo:g10:concentration-and-dilution:7}
377| 为什么配制准确浓度的溶液要用容量瓶，而不用带刻度的烧杯？
378| 为什么量取母液要用移液管，而不用量筒？
379| \end{exercise}
